"""Package cover images into 10,000-image zip batches and verify IA uploads.

Identifiers use a ten-digit cover ID. Its first four digits name the million-cover
item, and the next two name the 10,000-cover batch. Each size has its own item.
"""

import fcntl
import os
from contextlib import contextmanager
from datetime import datetime
from subprocess import run
from zipfile import ZIP_STORED, ZipFile

from openlibrary.coverstore import config, db

SIZES = ('', 's', 'm', 'l')


def _size(size):
    size = size.lower()
    if size not in SIZES:
        raise ValueError('size must be one of: original, s, m, l')
    return size


@contextmanager
def _archive_lock():
    """Serialize archive and finalization work sharing this data root."""
    folder = os.path.join(config.data_root, 'items')
    os.makedirs(folder, exist_ok=True)
    with open(os.path.join(folder, '.archive.lock'), 'a+b') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)


class Cover:
    def __init__(self, attributes):
        self.__dict__.update(attributes)

    @staticmethod
    def id_to_item_and_batch_id(cover_id):
        number = int(cover_id)
        if not 0 <= number <= 9999999999:
            raise ValueError('cover ID must fit in ten digits')
        digits = f'{number:010d}'
        return digits[:4], digits[4:6]

    @staticmethod
    def get_cover_url(cover_id, size='', ext='jpg', protocol='https'):
        size = _size(size)
        if protocol not in ('http', 'https'):
            raise ValueError('protocol must be http or https')
        item_id, batch_id = Cover.id_to_item_and_batch_id(cover_id)
        item = Batch.item_name(item_id, size)
        zip_name = os.path.basename(Batch.get_relpath(item_id, batch_id, size))
        suffix = f'-{size.upper()}' if size else ''
        member = f'{int(cover_id):010d}{suffix}.{ext}'
        return f'{protocol}://archive.org/download/{item}/{zip_name}/{member}'

    def files(self):
        for size in SIZES:
            field = 'filename' + (f'_{size}' if size else '')
            filename = getattr(self, field, None)
            if not filename:
                return
            path = os.path.join(config.data_root, 'localdisk', filename)
            if not os.path.isfile(path):
                return
            suffix = f'-{size.upper()}' if size else ''
            yield size, path, f'{int(self.id):010d}{suffix}.jpg'


class Batch:
    def __init__(self, item_id, batch_id, size=None):
        self.item_id, self.batch_id = self._norm_ids(item_id, batch_id)
        self.size = None if size is None else _size(size)

    @staticmethod
    def _norm_ids(item_id, batch_id):
        item, batch = int(item_id), int(batch_id)
        if not (0 <= item <= 9999 and 0 <= batch <= 99):
            raise ValueError('item or batch ID outside its range')
        return f'{item:04d}', f'{batch:02d}'

    @classmethod
    def item_name(cls, item_id, size=''):
        item_id, _ = cls._norm_ids(item_id, 0)
        return f'{_size(size) + "_" if size else ""}covers_{item_id}'

    @classmethod
    def get_relpath(cls, item_id, batch_id, size='', ext='zip'):
        item_id, batch_id = cls._norm_ids(item_id, batch_id)
        item = cls.item_name(item_id, size)
        return os.path.join('items', item, f'{item}_{batch_id}.{ext}')

    @classmethod
    def get_abspath(cls, item_id, batch_id, size='', ext='zip'):
        return os.path.join(config.data_root, cls.get_relpath(item_id, batch_id, size, ext))

    def process_pending(self, upload=False, finalize=False, test=False, uploader=None):
        uploader = uploader or Uploader()
        with _archive_lock():
            sizes = SIZES if self.size is None else (self.size,)
            for size in sizes:
                path = self.get_abspath(self.item_id, self.batch_id, size)
                if not os.path.isfile(path):
                    continue
                item = self.item_name(self.item_id, size)
                if upload and not test and not uploader.is_uploaded(item, os.path.basename(path)):
                    uploader.upload(item, [path])
            if finalize and not test:
                # A cover has all four sizes; publish it only after every zip
                # has been verified remotely. Missing local zips are allowed on
                # retries after a previously completed upload.
                if all(
                    uploader.is_uploaded(
                        self.item_name(self.item_id, size),
                        os.path.basename(self.get_abspath(self.item_id, self.batch_id, size)),
                    )
                    for size in SIZES
                ):
                    CoverDB.update_completed_batch(self.item_id, self.batch_id)
                    for size in SIZES:
                        path = self.get_abspath(self.item_id, self.batch_id, size)
                        if os.path.exists(path):
                            os.remove(path)
                    return True
            return False

    def finalize(self, start_id=None, test=False):
        return self.process_pending(finalize=True, test=test)


class ZipManager:
    def __init__(self):
        self.zipfiles = {}
        self.members = {}

    def get_zipfile(self, name):
        digits = name.split('-', 1)[0].split('.', 1)[0]
        item_id, batch_id = Cover.id_to_item_and_batch_id(digits)
        size = name.split('-', 1)[1][0].lower() if '-' in name else ''
        path = Batch.get_abspath(item_id, batch_id, size)
        if path not in self.zipfiles:
            os.makedirs(os.path.dirname(path), exist_ok=True)
            zf = ZipFile(path, 'a', compression=ZIP_STORED, allowZip64=True)
            self.zipfiles[path] = zf
            self.members[path] = set(zf.namelist())
        return self.zipfiles[path]

    def add_file(self, name, filepath, mtime):
        zf = self.get_zipfile(name)
        if name not in self.members[zf.filename]:
            from zipfile import ZipInfo

            date = datetime.fromtimestamp(mtime).timetuple()[:6]
            info = ZipInfo(name, date_time=max(date, (1980, 1, 1, 0, 0, 0)))
            info.compress_type = ZIP_STORED
            with open(filepath, 'rb') as source, zf.open(info, 'w') as target:
                while chunk := source.read(1024 * 1024):
                    target.write(chunk)
            self.members[zf.filename].add(name)
        return f'{os.path.basename(zf.filename)}/{name}'

    def close(self):
        for zf in self.zipfiles.values():
            zf.close()
        self.zipfiles.clear()
        self.members.clear()


def get_zipfile(name):
    return open_zipfile(name)


def open_zipfile(name):
    digits = name.split('-', 1)[0].split('.', 1)[0]
    item_id, batch_id = Cover.id_to_item_and_batch_id(digits)
    size = name.split('-', 1)[1][0].lower() if '-' in name else ''
    path = Batch.get_abspath(item_id, batch_id, size)
    os.makedirs(os.path.dirname(path), exist_ok=True)
    return ZipFile(path, 'a', compression=ZIP_STORED, allowZip64=True)


def count_files_in_zip(filepath):
    with ZipFile(filepath) as zf:
        return sum(name.lower().endswith('.jpg') for name in zf.namelist())


class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                   check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False):
        result = run(['ia', 'list', item], check=True, capture_output=True, text=True)
        found = zip_filename in (line.strip() for line in result.stdout.splitlines())
        if verbose:
            print(item, zip_filename, 'uploaded' if found else 'missing')
        return found


