    def update_completed_batch(item_id, batch_id, ext='jpg'):
        item_id, batch_id = Batch._norm_ids(item_id, batch_id)
        start_id = int(item_id) * 1000000 + int(batch_id) * 10000
        end_id = CoverDB._get_batch_end_id(start_id)
        connection = db.getdb()
        # PostgreSQL and SQLite both accept this bounded, parameterized update.
        transaction = connection.transaction()
        try:
            for cover in list(connection.select(
