class Uploader:
    def upload(self, itemname, filepaths):
        return run(['ia', 'upload', itemname, *filepaths, '--retries', '10'],
                   check=True, capture_output=True, text=True)

    @staticmethod
    def is_uploaded(item, zip_filename, verbose=False, filepath=None):
        result = run(['ia', 'metadata', item], check=True, capture_output=True, text=True)
        metadata = json.loads(result.stdout)
        files = metadata.get('files', [])
        remote = next((entry for entry in files if entry.get('name') == zip_filename), None)
        found = remote is not None
        if found and filepath is not None:
            digest = hashlib.md5()
            with open(filepath, 'rb') as source:
                for chunk in iter(lambda: source.read(1024 * 1024), b''):
                    digest.update(chunk)
            found = remote.get('md5', '').lower() == digest.hexdigest()
        if verbose:
            print(item, zip_filename, 'verified' if found else 'missing or mismatched')
        return found


